<?php
/** Orchard Ledger transport workflow endpoint: only the assigned provider can advance a request through recorded trip milestones. */
declare(strict_types=1);
require_once __DIR__ . '/../../includes/bootstrap.php';
require_method('POST');verify_csrf();$providerUser=require_role(['transport_provider']);$requestId=filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$next=normalize_text($_POST['status']??'',30);$transitions=['requested'=>['accepted','cancelled'],'accepted'=>['driver_assigned','cancelled'],'driver_assigned'=>['pickup_scheduled','cancelled'],'pickup_scheduled'=>['picked_up','cancelled'],'picked_up'=>['in_transit','cancelled'],'in_transit'=>['delivered','cancelled']];
if(!$requestId)json_response(false,'A valid transport request is required.',[],422);$pdo=db();$pdo->beginTransaction();
try{$request=fetch_one('SELECT tr.*,tp.user_id AS provider_user_id FROM transport_requests tr JOIN transport_providers tp ON tp.id=tr.provider_id WHERE tr.id=:id AND tp.user_id=:user FOR UPDATE',['id'=>$requestId,'user'=>$providerUser['id']]);if($request===null)throw new RuntimeException('This transport request is not assigned to your operation.');if(!in_array($next,$transitions[$request['status']]??[],true))throw new RuntimeException('This transport request cannot move to that status.');$fields=['status'=>$next,'id'=>$requestId];$sets=['status=:status'];if($next==='accepted'){$quote=positive_decimal($_POST['estimated_price']??null);if($quote===null)throw new RuntimeException('Enter the provider estimate before accepting this request.');$sets[]='estimated_price=:quote';$fields['quote']=$quote;}if($next==='driver_assigned'){$vehicleId=filter_input(INPUT_POST,'vehicle_id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$driver=normalize_text($_POST['driver_name']??'',120);$phone=normalize_text($_POST['driver_phone']??'',30);if(!$vehicleId||$driver===''||!preg_match('/^[0-9+()\-\s]{7,30}$/',$phone))throw new RuntimeException('Choose an eligible vehicle and enter valid driver details.');$vehicle=fetch_one('SELECT id,capacity_kg,is_refrigerated FROM vehicles WHERE id=:vehicle AND provider_id=:provider AND status="available" FOR UPDATE',['vehicle'=>$vehicleId,'provider'=>$request['provider_id']]);if($vehicle===null||(float)$vehicle['capacity_kg']<(float)$request['quantity_kg']||((int)$request['requires_refrigeration']===1&&(int)$vehicle['is_refrigerated']!==1))throw new RuntimeException('The selected vehicle cannot fulfil this load.');$sets[]='vehicle_id=:vehicle';$sets[]='driver_name=:driver';$sets[]='driver_phone=:phone';$fields+=['vehicle'=>$vehicleId,'driver'=>$driver,'phone'=>$phone];$pdo->prepare('UPDATE vehicles SET status="busy" WHERE id=:vehicle')->execute(['vehicle'=>$vehicleId]);}if($next==='delivered'&&$request['vehicle_id'])$pdo->prepare('UPDATE vehicles SET status="available" WHERE id=:vehicle')->execute(['vehicle'=>$request['vehicle_id']]);$note=normalize_text($_POST['provider_note']??'',500);if($note!==''){$sets[]='provider_note=:provider_note';$fields['provider_note']=$note;}$pdo->prepare('UPDATE transport_requests SET '.implode(',',$sets).' WHERE id=:id')->execute($fields);$pdo->prepare('INSERT INTO transport_status_history (transport_request_id,status,changed_by_user_id,note) VALUES (:request,:status,:actor,:note)')->execute(['request'=>$requestId,'status'=>$next,'actor'=>$providerUser['id'],'note'=>$note?:'Transport provider updated request status.']);create_notification((int)$request['farmer_id'],'transport_'.$next,'Transport request '.ucwords(str_replace('_',' ',$next)),'Your transport request '.$request['reference_code'].' is now '.str_replace('_',' ',$next),'transport/index.php','transport_request',$requestId);$pdo->commit();audit_log((int)$providerUser['id'],'transport_'.$next,'transport_requests',$requestId,['vehicle_assigned'=>$next==='driver_assigned']);json_response(true,'Transport request status updated to '.ucwords(str_replace('_',' ',$next)).'.',['request_id'=>$requestId,'status'=>$next,'redirect'=>app_url('transport/dashboard.php')]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(false,$e instanceof RuntimeException?$e->getMessage():'The transport status could not be updated.',[],422);}
